@import url(https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;700&family=Pacifico&family=Press+Start+2P&display=swap);

html,
body {
  block-size: 100%;
}

body {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  font-family: 'Press Start 2P', sans-serif;
  background-color: #000;
  block-size: 100%;
}

p {
  color: #fff;
  font-size: 48px;
  cursor: pointer;
  text-shadow: 0 0 5px #ffdd1b, 0 0 15px #ffdd1b, 0 0 30px #ffdd1b;
}

p:hover {
  animation: blink 0.5s infinite alternate;
}

@keyframes blink {
  0%,
  18%,
  22%,
  25%,
  53%,
  57%,
  100% {
  }

  20%,
  24%,
  55% {
  }
}
